const input = $json.body ?? $json;

const text = (value) =>
  value === null || value === undefined
    ? ''
    : String(value).trim();

const bool = (value) =>
  typeof value === 'boolean'
    ? value
    : ['true', '1', 'yes', 'on'].includes(
        text(value).toLowerCase()
      );

const callback_type =
  text(
    input.callback_type ||
    input.gateway_event_type ||
    'inbound_message'
  ).toLowerCase();

const clinic_name = text(input.clinic_name);
const client_name = text(input.client_name);
const provider_name = text(input.provider_name);
const channel = text(input.channel).toLowerCase();
const api_key = text(input.api_key);
const signature_verified = bool(input.signature_verified);
const verification_reference =
  text(input.verification_reference);
const source_ip = text(input.source_ip);

const external_event_id =
  text(
    input.external_event_id ||
    input.event_id
  );

const external_message_id =
  text(
    input.external_message_id ||
    input.message_id
  );

const external_conversation_id =
  text(
    input.external_conversation_id ||
    input.conversation_id ||
    input.thread_id
  );

const sender =
  text(
    input.sender ||
    input.from ||
    input.mobile
  );

const message_type =
  text(input.message_type || 'text').toLowerCase();

const message_text =
  text(
    input.message_text ||
    input.text ||
    input.content
  );

const language =
  text(input.language || 'unknown').toLowerCase();

const outbound_message_id =
  Number(input.outbound_message_id ?? 0);

const provider_message_id =
  text(
    input.provider_message_id ||
    input.message_id
  );

const delivery_status =
  text(
    input.delivery_status ||
    input.status ||
    'unknown'
  ).toLowerCase();

const event_at =
  text(
    input.event_at ||
    input.timestamp
  ) ||
  new Date().toISOString();

const error_code = text(input.error_code);
const error_message = text(input.error_message);

const webhook_base_url =
  text(
    input.webhook_base_url ||
    'http://n8n:5678/webhook'
  ).replace(/\/+$/, '');

const confirm_callback =
  bool(input.confirm_callback);

let attachments = input.attachments ?? [];
let raw_payload = input.raw_payload ?? input;

try {
  if (typeof attachments === 'string') {
    attachments =
      JSON.parse(attachments || '[]');
  }
} catch {
  attachments = [];
}

try {
  if (typeof raw_payload === 'string') {
    raw_payload =
      JSON.parse(raw_payload || '{}');
  }
} catch {
  raw_payload = {
    raw: String(raw_payload),
  };
}

if (!Array.isArray(attachments)) {
  attachments = [];
}

if (
  !raw_payload ||
  Array.isArray(raw_payload) ||
  typeof raw_payload !== 'object'
) {
  raw_payload = {};
}

const errors = [];

if (
  !['inbound_message', 'delivery_status'].includes(
    callback_type
  )
) {
  errors.push({
    field: 'callback_type',
    message: 'نوع Callback معتبر نیست.',
  });
}

for (const [field, value] of [
  ['clinic_name', clinic_name],
  ['client_name', client_name],
  ['provider_name', provider_name],
  ['channel', channel],
  ['external_event_id', external_event_id],
]) {
  if (!value) {
    errors.push({
      field,
      message: `${field} الزامی است.`,
    });
  }
}

if (
  callback_type === 'inbound_message' &&
  !external_message_id
) {
  errors.push({
    field: 'external_message_id',
    message: 'شناسه پیام ورودی الزامی است.',
  });
}

if (
  callback_type === 'inbound_message' &&
  !external_conversation_id
) {
  errors.push({
    field: 'external_conversation_id',
    message: 'شناسه مکالمه ورودی الزامی است.',
  });
}

if (
  callback_type === 'inbound_message' &&
  !message_text
) {
  errors.push({
    field: 'message_text',
    message: 'متن یا متن استخراج‌شده پیام الزامی است.',
  });
}

if (
  callback_type === 'delivery_status' &&
  (
    (
      !Number.isInteger(outbound_message_id) ||
      outbound_message_id < 1
    ) &&
    !provider_message_id
  )
) {
  errors.push({
    field: 'delivery_reference',
    message: 'شناسه داخلی یا Provider Message ID الزامی است.',
  });
}

if (Number.isNaN(Date.parse(event_at))) {
  errors.push({
    field: 'event_at',
    message: 'زمان Callback معتبر نیست.',
  });
}

if (!/^https?:\/\/.+/i.test(webhook_base_url)) {
  errors.push({
    field: 'webhook_base_url',
    message: 'آدرس Webhook معتبر نیست.',
  });
}

if (confirm_callback !== true) {
  errors.push({
    field: 'confirm_callback',
    message: 'پردازش Callback باید تأیید شود.',
  });
}

const normalized_payload = {
  provider_name,
  provider_callback_type: callback_type,
  original_status: delivery_status,
};

return [{
  json: {
    callback_type,
    gateway_url:
      `${webhook_base_url}/clinic/gateway/events/process`,
    gateway_payload: {
      gateway_event_type: callback_type,
      clinic_name,
      client_name,
      provider_name,
      channel,
      api_key,
      signature_verified,
      verification_reference,
      source_ip,
      external_event_id,
      external_message_id,
      external_conversation_id,
      sender,
      message_type,
      message_text,
      attachments,
      language,
      request_timestamp: event_at,
      outbound_message_id,
      provider_message_id,
      delivery_event_type: delivery_status,
      delivery_event_at: event_at,
      error_code,
      error_message,
      normalized_payload,
      raw_payload,
      webhook_base_url,
      confirm_gateway: true,
    },
    validation_status:
      errors.length === 0 ? 'valid' : 'invalid',
    errors,
  },
}];
